            weak = np.maximum(np.abs(d[1:-2]), np.abs(d[2:-1])) < 1.75 * scale
            for j in np.flatnonzero(turn & weak):
                smoothed[j + 1:j + 4] = np.linspace(
                    smoothed[j], smoothed[j + 4], 5
                )[1:4]

        # A second pass matters because flattening one narrow extremum can expose
        # an adjacent residual zig-zag. Broad or prominent extrema are untouched.
